var cd = new countdown (textCont.getElement ('i'), {
start: 120,
secondOnly: true,
callback: function (e ) {
el.removeClass ('disabled');
textCont.innerHTML = '重发验证码';
}
});
Query.send (url, el, data, function (rs ) {
if (rs.error ) {
changeCode (Module.element (modname, 'img.auto-change-verify-handle'));
cd.stop ();
el.removeClass ('disabled');
textCont.innerHTML = '重发验证码';
}
});
}

